const input = $input.item.json;
const periodo = input.periodo || 'Próximos 14 días';
const datosCalendario = Array.isArray(input.dataOriginal) ? input.dataOriginal : [];
const resultadosArray = Array.isArray(input.resultados) ? input.resultados : [];

if (resultadosArray.length === 0) {
  throw new Error("[ERROR]: No se recibió el array 'resultados' con la predicción del modelo.");
}

function aDecimal(v) {
  if (v === null || v === undefined || v === '') return null;
  const num = Number(v);
  if (isNaN(num)) return null;
  return num > 1.0 ? num / 100 : num;
}

let valoresFinales = [];
let fechasSerie = [];
let etiquetas = [];
let contextoExterno = [];

// 1. CRUZAR PREDICCIÓN BASE CON REGLAS DE NEGOCIO
for (let i = 0; i < 14; i++) {
  const resItem = resultadosArray[i] || {};
  const d = datosCalendario[i] || {};

  // Extraer la fecha directamente de la variable "Fecha" de los resultados
  // (Dejamos minúsculas y CheckIn como plan B por si las moscas, pero priorizamos "Fecha")
  let fechaDia = resItem.Fecha || resItem.fecha || resItem.CheckIn || d.Fecha || d.fecha || `Día ${i + 1}`;

  fechasSerie.push(fechaDia);

  // Generar etiqueta corta para la gráfica (ej: 25/07)
  let etiqueta = `D${i + 1}`;
  if (fechaDia && String(fechaDia).includes('-')) {
    const parts = String(fechaDia).split('-');
    if (parts.length >= 3) etiqueta = `${parts[2]}/${parts[1]}`;
  }
  etiquetas.push(etiqueta);

  // Ocupación Base (del modelo puro)
  let rawBase = Number(resItem.ocup_final_predicha ?? resItem.ocupacion_base ?? resItem.ocupacion_actual ?? 0);
  let ocupacionBase = aDecimal(rawBase) || 0;

  // Aplicar Ajuste (Clima / Festivos)
  const ajustePct = Number(d.ajuste_pct || 0);
  let ocupacionFinal = ocupacionBase * (1 + (ajustePct / 100));

  // Limitar topes (0% a 100%)
  if (ocupacionFinal > 1) ocupacionFinal = 1;
  if (ocupacionFinal < 0) ocupacionFinal = 0;

  valoresFinales.push(ocupacionFinal);

  // Guardar contexto enriquecido para la IA
  contextoExterno.push({
    fecha: fechaDia, 
    ocupacion_base: Number(ocupacionBase.toFixed(4)),
    ajuste_aplicado_pct: ajustePct,
    motivo_ajuste: d.motivo_ajuste || "Sin ajuste",
    ocup_final_predicha: Number(ocupacionFinal.toFixed(4)), 
    ocupacion_actual: aDecimal(resItem.ocupacion_actual ?? d.ocupacion_actual_pct),
    pickup_predicho: resItem.pickup_predicho ?? null,
    ocupacion_mismo_periodo_anio_anterior: aDecimal(d.ocupacion_mismo_periodo_anio_anterior),
    pickup_ultimos_7_dias: d.pickup_ultimos_7_dias ?? null,
    es_vacaciones_escolares: d.es_vacaciones_escolares ?? false,
    es_festivo: d.es_festivo ?? false,
    clima: d.clima || null
  });
}

// 2. CÁLCULOS ESTADÍSTICOS 
const n = valoresFinales.length;
const media = valoresFinales.reduce((a, b) => a + b, 0) / n;
const maximo = Math.max(...valoresFinales);
const minimo = Math.min(...valoresFinales);
const diaMax = valoresFinales.indexOf(maximo) + 1;
const diaMin = valoresFinales.indexOf(minimo) + 1;

const varianza = valoresFinales.reduce((a, b) => a + Math.pow(b - media, 2), 0) / n;
const desviacion = Math.sqrt(varianza);

const xs = valoresFinales.map((_, i) => i);
const mediaX = xs.reduce((a, b) => a + b, 0) / n;
const numTend = xs.reduce((acc, x, i) => acc + (x - mediaX) * (valoresFinales[i] - media), 0);
const denTend = xs.reduce((acc, x) => acc + Math.pow(x - mediaX, 2), 0);
const pendiente = denTend !== 0 ? numTend / denTend : 0;
const tendencia = pendiente > 0.001 ? 'ascendente' : pendiente < -0.001 ? 'descendente' : 'estable';

const UMBRAL_CRITICO = 0.4;
const diasBajoUmbral = valoresFinales.filter(v => v < UMBRAL_CRITICO).length;

const semana1 = valoresFinales.slice(0, 7);
const semana2 = valoresFinales.slice(7, 14);
const mediaSemana1 = semana1.reduce((a, b) => a + b, 0) / (semana1.length || 1);
const mediaSemana2 = semana2.reduce((a, b) => a + b, 0) / (semana2.length || 1);
const variacionSemanal = mediaSemana2 - mediaSemana1;

// 3. CONFIGURAR QUICKCHART
const techoGrafico = Math.min(100, Math.ceil((Math.max(maximo, UMBRAL_CRITICO) * 100 * 1.25) / 10) * 10);
const chartConfig = {
  type: 'line',
  data: {
    labels: etiquetas,
    datasets: [
      { 
        label: 'Ocupación prevista (Ajustada)', 
        data: valoresFinales.map(v => Number((v * 100).toFixed(1))), 
        borderColor: '#2563eb', 
        backgroundColor: 'rgba(37,99,235,0.15)', 
        fill: true, 
        tension: 0.3, 
        pointRadius: 3 
      },
      { 
        label: 'Umbral crítico', 
        data: valoresFinales.map(() => UMBRAL_CRITICO * 100), 
        borderColor: '#dc2626', 
        borderDash: [6, 6], 
        pointRadius: 0, 
        fill: false 
      }
    ]
  },
  options: {
    title: { display: true, text: `Predicción de ocupación · ${periodo}` },
    scales: { yAxes: [{ scaleLabel: { display: true, labelString: 'Ocupación (%)' }, ticks: { min: 0, max: techoGrafico } }] }
  }
};
const chartUrl = 'https://quickchart.io/chart?width=760&height=360&backgroundColor=white&c=' + encodeURIComponent(JSON.stringify(chartConfig));

// 4. RESUMEN SEMANAL
function resumenSemana(valoresSemana, contextoSemana) {
  const nS = valoresSemana.length || 1;
  const mediaS = valoresSemana.reduce((a, b) => a + b, 0) / nS;
  return {
    media: Number(mediaS.toFixed(3)),
    maximo: Number(Math.max(...valoresSemana).toFixed(3)),
    minimo: Number(Math.min(...valoresSemana).toFixed(3)),
    dias_vacaciones_escolares: contextoSemana.filter(c => c.es_vacaciones_escolares === true).length,
    dias_buen_tiempo: contextoSemana.filter(c => c.clima && c.clima.precipitacion < 1 && c.clima.temp_max > 20).length,
    dias_mal_tiempo: contextoSemana.filter(c => c.clima && c.clima.precipitacion > 5).length
  };
}

const resumenSemanal = {
  semana1: resumenSemana(semana1, contextoExterno.slice(0, 7)),
  semana2: resumenSemana(semana2, contextoExterno.slice(7, 14)),
  variacion_ocupacion_pp: Number((variacionSemanal * 100).toFixed(1))
};

return [{
  json: {
    periodo,
    estadisticas: {
      media: Number(media.toFixed(3)),
      maximo: Number(maximo.toFixed(3)),
      diaMax,
      fechaMax: fechasSerie[diaMax - 1] || null,
      minimo: Number(minimo.toFixed(3)),
      diaMin,
      fechaMin: fechasSerie[diaMin - 1] || null,
      desviacion: Number(desviacion.toFixed(3)),
      tendencia,
      pendiente: Number(pendiente.toFixed(4)),
      diasBajoUmbral,
      umbralCritico: UMBRAL_CRITICO,
      mediaSemana1: Number(mediaSemana1.toFixed(3)),
      mediaSemana2: Number(mediaSemana2.toFixed(3)),
      variacionSemanal: Number(variacionSemanal.toFixed(3)),
      fechas: fechasSerie,
      contexto_externo: contextoExterno,
      resumen_semanal: resumenSemanal
    },
    chart_url: chartUrl
  }
}];
